import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2, x3 = x
    return 0.1 * (x1**3 + x2**3 + x3**3) + 0.6 * (x1**2 + x2**2 + x3**2) + 0.05 * (x1 + x2 - x3)

import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    x = np.clip(x, -5, 5)

    dim = len(x)

    sinc_sum = 0.0
    for i in range(dim):
      sinc_sum += np.sinc(x[i] + (i*0.5))

    sigmoid = 1.0 / (1.0 + np.exp(-np.sum(x)))

    interaction_term = 0.0
    for i in range(dim):
        for j in range(i + 1, dim):
            interaction_term += 0.1 * x[i]**2 * x[j]**2

    return float(0.5*sinc_sum + 0.2 * sigmoid + 0.3 * interaction_term)
